mapper.select:
SELECT * FROM ( SELECT a.*, b.al_name as al_name FROM al_task a LEFT JOIN al_data_clean b ON a.al_id = b.id WHERE a.al_class = 'alDataCleaning' AND a.server_url=#{serverUrl}
UNION
SELECT a.*, c.al_name as al_name FROM al_task a LEFT JOIN al_knowledge_extraction c ON a.al_id = c.id WHERE a.al_class = 'alKnowledgeExtraction' AND a.server_url=#{serverUrl}
UNION
SELECT a.*, d.model_name as al_name FROM al_task a LEFT JOIN al_fault_diagnosis d ON a.al_id = d.id WHERE a.al_class = 'alFaultDiagnosis' AND a.server_url=#{serverUrl}
UNION
SELECT a.*, e.model_name as al_name FROM al_task a LEFT JOIN al_state_evaluation e ON a.al_id = e.id WHERE a.al_class = 'alStateEvaluation' AND a.server_url=#{serverUrl}
UNION
SELECT a.*, '算法审核' as al_name FROM al_task a WHERE a.al_class = 'autoTest' AND a.server_url=#{serverUrl}
UNION SELECT a.*, '自动获取评价指标' as al_name FROM al_task a WHERE a.al_class = 'autoGetMetrics' AND a.server_url=#{serverUrl}
UNION SELECT a.*, '在线训练' as al_name FROM al_task a WHERE a.al_class = 'onlineTrain' AND a.server_url=#{serverUrl} ) t WHERE t.al_name != '' AND t.server_url = #{serverUrl} ORDER BY t.id DESC;
